const results = await Promise.all([
  tools.exec_command({cmd:"rg -n \"DB|database|postgres|mysql|sqlite\" cmd server store | head -200","workdir":"/bench/repo","max_output_tokens:12000}),
  tools.exec_command({cmd:"sed -n '1,220p' store/db/sqlite/memo.go; sed -n '1,180p' store/db/postgres/memo.go; sed -n '1,160p' store/db/mysql/memo.go","workdir":"/bench/repo","max_output_tokens":12000}),
  tools.exec_command({cmd:"rg -n \"CreateMemo|memo.*Create|SaveMemo|UpsertMemo|Memo.*Store\" store server | head -200","workdir":"/bench/repo","max_output_tokens":12000})
]); results.forEach(r=>text(r.output));

const cmds = [
  ["rg -n \"DB|database|postgres|mysql|sqlite\" cmd server store | head -200",12000],
  ["sed -n '1,220p' store/db/sqlite/memo.go; sed -n '1,180p' store/db/postgres/memo.go; sed -n '1,160p' store/db/mysql/memo.go",12000],
  ["rg -n \"CreateMemo|memo.*Create|SaveMemo|UpsertMemo|Memo.*Store\" store server | head -200",12000]
];
const rs = await Promise.all(cmds.map(([cmd,max_output_tokens])=>tools.exec_command({cmd,workdir:"/bench/repo",max_output_tokens})));
rs.forEach(r=>text(r.output));

